'use strict';
// ---------- study hours: 12 tick boxes (future days locked) ----------
function hourGrid(o){const n=hrs(o),Tg=tgt(o),pct=Math.min(100,Math.round(n/Tg*100)),fut=o>co();let b='';
for(let i=0;i<12;i++){const x=i<n;b+=`<button class="hbox${x?' x':''}${i>=Tg?' extra':''}" data-act="hr" data-o="${o}" data-i="${i}" aria-pressed="${x}" aria-label="${T('hr.upto',{n:i+1})}"${fut?' disabled':''}>${x?'✕':i+1}</button>`}
return `<div class="hours">${b}</div><div class="progress gold" style="margin-top:14px"><span style="width:${pct}%"></span></div>`}
const hrMsg=o=>{const n=hrs(o),Tg=tgt(o);return o>co()?T('hr.future'):n>=Tg?T('hr.hit')+(n>Tg?' '+T('hr.bonus',{n:n-Tg}):''):n==0?T('hr.first'):T('hr.left',{n:Tg-n})};
const hrBadge=o=>{const n=hrs(o),Tg=tgt(o);return `<span class="pending-count" style="${n>=Tg?'background:var(--gold-bg);color:var(--gold-ink)':''}">${n} / ${Tg} ${T('hr.hrs')}</span>`};
function hoursPanel(w,d){const o=ord(w,d),x=dd(w,d);
return panel(`${T('hr.title')} · ${x.day} ${x.mon}`,hrMsg(o),hrBadge(o),hourGrid(o)+`<div class="row2" style="margin-top:14px;justify-content:space-between"><span class="paneldesc">${T('hr.hint')}</span><span class="row2"><span class="chip">${T('hr.streak')} <b>${T('n.days',{n:streak()})}</b></span><label class="paneldesc">${T('hr.target')} ${tgSel()} ${T('hr.fromToday')}</label></span></div>`)}
function hoursDash(){const o=co();let tot=0,bars='';for(let d=1;d<=7;d++){const k=ord(cur.w,d),n=hrs(k);tot+=n;bars+=`<div${k==o?' class="now"':''}><i style="height:${Math.max(3,n/12*70)}px;background:${n>=tgt(k)?'var(--gold)':'var(--navy)'}"></i>${n}<span>${dd(cur.w,d).dow.slice(0,3)}</span></div>`}
const x=dd(cur.w,cur.d);
return panel(`${T('hr.title')} · ${T('w.today')} ${x.day} ${x.mon}`,hrMsg(o),hrBadge(o),hourGrid(o)+`<p class="paneldesc" style="margin:18px 0 10px">${T('hr.week',{n:TG})}</p><div class="hbars">${bars}</div><div class="row2" style="margin-top:14px"><span class="chip">${T('hr.thisWeek')} <b>${T('n.hours',{n:tot})}</b></span><span class="chip">⏱ ${T('hr.logged')} <b>${hm(SEC[o])}</b></span><span class="chip">${T('hr.streak')} <b>${T('n.days',{n:streak()})}</b></span><label class="paneldesc">${T('hr.target')} ${tgSel()} ${T('hr.fromToday')}</label></div>`)}

// ---------- spaced revision ----------
function revRow(r){const p=P.find(x=>x.id==r.pid);if(!p||p.arch)return'';
return `<div class="task"><button class="check${r.done?' done':''}" data-rev="${r.id}" aria-pressed="${r.done}" aria-label="${T('a.tick')}: ${esc(p.t)}">✓</button><div class="taskbody"><div class="tasktitle${r.done?' done':''}">${esc(p.t)}</div><div class="taskmeta"><span class="revtag">${T('rev.tag',{n:r.step})}</span><span>${esc(sn(p.s,p.w))}</span><span>·</span><span>${T('rev.first',{d:lab(p.ow,p.od)})}</span></div></div><button class="noteicon" data-act="revdel" data-r="${r.id}" aria-label="${T('rev.cancel')}">✕</button></div>`}
function revPanel(o){const a=revsOn(o).filter(r=>P.some(p=>p.id==r.pid&&!p.arch));if(!a.length)return'';
return panel(T('rev.title'),T('rev.desc',{d:a.filter(r=>r.done).length,n:a.length}),'<span class="revtag">REVISE</span>',`<div class="task-list">${a.map(revRow).join('')}</div>`)}
function overdueHtml(){const a=overdueRevs();if(!a.length)return'';
return panel(T('rev.overdue'),T('rev.overdueDesc'),`<span class="pending-count">${T('n.items',{n:a.length})}</span>`,`<div class="task-list">${a.map(revRow).join('')}</div><div style="margin-top:14px"><button class="secondary" data-act="revtoday">${T('rev.allToday')}</button></div>`)}
function revUI(p){const mine=revs.filter(r=>r.pid==p.id&&!r.done);
return `<p class="paneldesc" style="margin:14px 0 6px">${T('rev.when')}</p><div class="row2">${LAD.map(n=>`<button class="chip" data-act="revset" data-id="${p.id}" data-n="${n}">${T('rev.after',{n})}</button>`).join('')}</div><div class="row2" style="margin-top:8px"><select id="rvd" aria-label="${T('rev.day')}">${ALL.filter(x=>ord(...x)>co()).map(([w,d])=>`<option value="${ord(w,d)}">${lab(w,d)} · ${dd(w,d).day} ${dd(w,d).mon}</option>`).join('')}</select><button class="mini" data-act="revpick" data-id="${p.id}">${T('rev.setDay')}</button></div>${mine.length?`<div class="row2" style="margin-top:8px">${mine.map(r=>`<span class="chip">${dlab(r.o)} <button class="link danger" data-act="revdel" data-r="${r.id}" aria-label="${T('rev.cancel')}">✕</button></span>`).join('')}</div>`:''}`}

// ---------- day close ----------
function modalHtml(){const ps=act(cur.w,cur.d),left=ps.length-cnt(ps),x=dd(cur.w,cur.d),ex=refl.find(r=>r.w==cur.w&&r.d==cur.d),rv=revsOn(co()).filter(r=>!r.done).length;
return `<div class="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="mt"><div class="eyebrow">${T('close.eyebrow')} · ${lab(cur.w,cur.d)} · ${x.day} ${x.mon}</div><h2 id="mt" style="font-size:22px;font-family:Fraunces,Georgia,serif;color:var(--navy-deep);margin-bottom:6px">${T('close.title')}</h2>
<p class="paneldesc" style="margin-bottom:12px">${T('close.sum',{d:cnt(ps),n:ps.length,h:hrs(co()),t:tgt(co())})} · ${T('pl.vs',{p:fmtM(planMin(co())),l:hm(SEC[co()])})}${left?' · '+T('close.left',{n:left}):''}${rv?' · '+T('close.rev',{n:rv}):''}</p>${cur.d==7?`<div class="wsum"><div class="eyebrow">${T('close.week',{w:cur.w})}</div>${weekSummary(cur.w,1)}</div>`:''}
<div class="eyebrow" style="margin:4px 0 8px">${T('close.hours')}</div>${hourGrid(co())}<textarea id="cr" style="margin-top:14px" aria-label="${T('notes.refl')}" placeholder="${T('close.ph')}">${esc(closeDraft??(ex?ex.t:''))}</textarea>
<div class="row2" style="margin-top:14px;justify-content:flex-end"><button class="secondary" data-act="closecancel">${T('cancel')}</button><button class="secondary" data-act="closeskip">${T('close.skip')}</button><button class="primary" data-act="closego">${T('close.save')}</button></div></div></div>`}

// ---------- shared rows / cards ----------
function taskRow(p){const d=done.has(p.id),n=notes[p.id];
return `<div class="task"><button class="check${d?' done':''}" data-id="${p.id}" aria-pressed="${d}" aria-label="${T('a.tick')}: ${esc(p.t)}">✓</button><div class="taskbody"><div class="tasktitle${d?' done':''}">${esc(p.t)}</div><div class="taskmeta">${pr(p.p)}<span>${esc(sn(p.s,p.w))}</span><span>·</span><span>${lab(p.w,p.d)}</span>${(e=>e||p.sec>=60?`<span class="tag${e&&p.sec>e*60?' over':''}" title="${T('pl.tip')}">⏱ ${p.sec>=60?hm(p.sec)+(e?' / ':''):''}${e?fmtM(e):''}</span>`:'')(estOf(p))}${p.from?`<span class="fromtag">${T('from',{d:p.from})}</span>`:''}${revs.some(r=>r.pid==p.id&&!r.done)?`<span class="revtag">↻ ${T('rev.set')}</span>`:''}</div>${n&&noteOpen!=p.id?`<div class="tasknote">${esc(n)}</div>`:''}${noteOpen==p.id?`<div style="margin-top:10px"><textarea id="nt" aria-label="${T('note')}">${esc(n||'')}</textarea><div class="row2" style="margin-top:10px"><label class="paneldesc">${T('pl.est')} <input type="number" id="nest" min="0" value="${p.est||''}" placeholder="${SMIN[p.s]||''}" style="width:84px"></label><label class="paneldesc">${T('pl.spent')} <input type="number" id="nspent" min="0" value="${Math.round((p.sec||0)/60)}" style="width:84px"></label></div>${revUI(p)}<div class="row2" style="margin-top:14px"><button class="mini p" data-act="notesave" data-id="${p.id}">${T('save')}</button><button class="mini" data-act="notecancel">${T('cancel')}</button>${n?`<button class="mini danger" data-act="notedel" data-id="${p.id}">${T('delete')}</button>`:''}</div></div>`:''}</div><button class="noteicon play${pOn({p:p.id})?' on':''}" data-act="pomo" data-id="${p.id}" aria-label="${T('a.timer')}: ${esc(p.t)}">▶</button><button class="noteicon pin${pin.has(p.id)?' on':''}" data-act="pin" data-id="${p.id}" aria-pressed="${pin.has(p.id)}" aria-label="${T('a.pin')}">${pin.has(p.id)?'★':'☆'}</button><button class="noteicon${n?' hasnote':''}" data-act="note" data-id="${p.id}" aria-label="${T('a.note')}">${n?'▤':'＋'}</button></div>`}
function subjBars(ps,w){return `<div class="subject-list">${SUBJ.map(([k])=>{const s=ps.filter(p=>p.s==k);if(!s.length)return'';const c=cnt(s),x=Math.round(c/s.length*100);return `<div class="subject-row"><div class="subject-name">${esc(sn(k,w))}</div><div class="progress"><span style="width:${x}%"></span></div><div class="subject-count">${c} / ${s.length}</div></div>`}).join('')}</div>`}
function strip(sel,w=cur.w){let h='<div class="weekstrip">';for(let d=1;d<=7;d++){const ps=act(w,d),x=dd(w,d),t=w==cur.w&&d==cur.d;
h+=`<button class="weekday${pc(ps)==100&&ps.length?' complete':''}${t?' today':''}${ord(w,d)>co()?' future':''}${sel==d?' sel':''}" data-act="wk" data-w="${w}" data-d="${d}" aria-label="${labf(w,d)}"><div class="day">${x.dow}${t?' · '+T('w.todayCap'):''}</div><div class="date">${x.day}</div><div class="dn">${lab(w,d)}${(m=>m?' · '+hShort(m):'')(planMin(ord(w,d)))}</div><div class="mini-bar"><span style="width:${pc(ps)}%"></span></div></button>`}return h+'</div>'}
function stats(){const A=P.filter(p=>!p.arch),hl=A.filter(p=>p.p=='High'&&!done.has(p.id)&&ord(p.w,p.d)<=co()).length;
return `<section class="stats"><div class="stat featured"><div class="statlabel"><span class="dot"></span> ${T('st.overall')}</div><div class="statvalue">${pc(A)}<small>%</small></div><div class="statfoot">${T('st.overallFoot',{d:co(),n:planLen()})}</div></div><div class="stat"><div class="statlabel">✓ ${T('st.done')}</div><div class="statvalue">${cnt(A)}</div><div class="statfoot">${T('st.doneFoot')}</div></div><div class="stat"><div class="statlabel">↗ ${T('st.pending')}</div><div class="statvalue">${pendCount()}</div><div class="statfoot">${T('st.pendingFoot')}</div></div><div class="stat"><div class="statlabel">◎ ${T('st.high')}</div><div class="statvalue">${hl}</div><div class="statfoot">${T('st.highFoot')}</div></div></section>`}
function reflCard(r,ctl){const x=dd(r.w,r.d);return `<div class="reflection"><div class="reflection-meta"><span class="quoteicon">✎</span><span>${lab(r.w,r.d).toUpperCase()}</span><span>·</span><span>${x.day} ${x.mon}</span></div><p>${esc(r.t)}</p><div class="reflection-foot"><span>${T('notes.daily')}</span>${ctl?`<span><button class="link" data-act="rfedit" data-w="${r.w}" data-d="${r.d}">${T('edit')}</button> · <button class="link danger" data-act="rfdel" data-w="${r.w}" data-d="${r.d}">${T('delete')}</button></span>`:`<button class="link" data-tab="notes">↗ ${T('notes.read')}</button>`}</div></div>`}

// planned time vs the daily target
function planNote(o){const m=planMin(o),t=tgt(o)*60;if(!m)return'';const d=m-t;
return `<p class="paneldesc plnote${d>0?' over':''}" style="margin:10px 0 0">${d>0?T('pl.over',{t:fmtM(d)}):d<0?T('pl.free',{t:fmtM(-d)}):T('pl.exact')}</p>`}
// ---------- today's focus: own to-dos + ★ pinned tasks ----------
// Today's focus: your own to-dos + ★ topics; today's remaining High-priority topics are offered below until you have 3
function focusPanel(dash){const o=co(),own=FOC.filter(f=>f.o==o),pinned=P.filter(p=>pin.has(p.id)&&!p.arch&&(!done.has(p.id)||ord(p.w,p.d)==o)),n=own.length+pinned.length,
sugg=n>=3?[]:act(cur.w,cur.d).filter(p=>!done.has(p.id)&&!pin.has(p.id)&&p.p=='High').slice(0,3-n),dn=own.filter(f=>f.done).length+cnt(pinned),tot=own.reduce((a,f)=>a+(f.est||0),0)+pinned.reduce((a,p)=>a+estOf(p),0);
const ownRow=f=>`<div class="task"><button class="check${f.done?' done':''}" data-foc="${f.id}" aria-pressed="${f.done}" aria-label="${T('a.tick')}: ${esc(f.t)}">✓</button><div class="taskbody"><div class="tasktitle${f.done?' done':''}">${esc(f.t)}</div><div class="taskmeta">${pr(f.p)}<span class="tag">${T('foc.own')}</span>${f.est?`<span class="tag">⏱ ${fmtM(f.est)}</span>`:''}${f.from?`<span class="fromtag">${T('from',{d:f.from})}</span>`:''}</div></div><button class="noteicon play${pOn({f:f.id})?' on':''}" data-act="pomo" data-f="${f.id}" aria-label="${T('a.timer')}">▶</button><button class="noteicon" data-act="focdel" data-f="${f.id}" aria-label="${T('remove')}">✕</button></div>`;
const sugRow=p=>`<div class="srow fsug"><span><span class="tasktitle">${esc(p.t)}</span><small>${esc(sn(p.s,p.w))}${estOf(p)?' · ⏱ '+fmtM(estOf(p)):''}</small></span><button class="mini" data-act="pin" data-id="${p.id}">☆ ${T('foc.addIt')}</button></div>`;
const form=`<div class="tform" style="margin-top:14px"><select id="fos" aria-label="${T('subject')}"><option value=""${FF.s?'':' selected'}>${T('foc.ownOpt')}</option>${SUBJ.map(([k])=>`<option value="${k}"${FF.s==k?' selected':''}>${esc(sn(k,cur.w))}</option>`).join('')}</select><input type="text" id="fadd" placeholder="${T('foc.ph')}" aria-label="${T('topic')}"><input type="number" id="fam" min="0" class="tmin" placeholder="${T('pl.minPh')}" aria-label="${T('ce.min')}"><select id="fap" aria-label="${T('priority')}">${priOpts(FF.p)}</select><button class="primary" data-act="focadd">+ ${T('add')}</button></div>`;
return panel(T('foc.title'),n?T('foc.desc2',{d:dn,n,t:fmtM(tot)}):T('foc.empty'),dash?`<button class="link" data-tab="today">${T('openToday')}</button>`:'',
`<div class="task-list">${own.map(ownRow).join('')}${pinned.map(taskRow).join('')}</div>${sugg.length?`<p class="paneldesc" style="margin:${n?14:0}px 0 2px">${T('foc.sugg')}</p>${sugg.map(sugRow).join('')}`:''}${form}<p class="paneldesc" style="margin-top:6px">${T('foc.formHint')}</p>`)}
function todayProg(){const ps=act(cur.w,cur.d),x=pc(ps),left=ps.length-cnt(ps),own=FOC.filter(f=>f.o==co()),rv=revsOn(co()).filter(r=>P.some(p=>p.id==r.pid&&!p.arch));
return panel(T('tp.title'),`${labf(cur.w,cur.d)} · ${T('tp.desc')}`,`<button class="link" data-tab="today">${T('openToday')}</button>`,
`<div class="tbig"><span class="tval">${x}<small>%</small></span><span class="paneldesc">${ps.length?T('tp.done',{d:cnt(ps),n:ps.length})+' · '+(left?T('tp.left',{n:left}):T('tp.complete')):T('tp.none')}</span></div><div class="progress big${x==100?' gold':''}"><span style="width:${x}%"></span></div>
${planNote(co())}<div class="row2" style="margin-top:14px"><span class="chip">${T('tp.hours')} <b>${hrs(co())} / ${tgt(co())}</b></span><span class="chip">📋 ${T('pl.plan')} <b>${fmtM(planMin(co()))}</b></span><span class="chip">⏱ ${T('hr.logged')} <b>${hm(SEC[co()])}</b></span>${own.length?`<span class="chip">${T('foc.own')} <b>${own.filter(f=>f.done).length} / ${own.length}</b></span>`:''}${rv.length?`<span class="chip">${T('tp.revise')} <b>${rv.filter(r=>r.done).length} / ${rv.length}</b></span>`:''}${(f=>f?`<span class="chip${f.p<80?' err':''}">🎯 ${T('fg.focus')} <b>${f.p}%</b> · ${T('fg.left',{n:f.n})}</span>`:'')(focusPct(co(),co()))}</div>`)}
function dayList(){const ps=act(cur.w,cur.d);return SUBJ.map(([k])=>{const s=ps.filter(p=>p.s==k);if(!s.length)return'';const c=cnt(s);
return `<div class="dsub"><div class="dsh"><span class="subject-name">${esc(sn(k,cur.w))}</span><span class="subject-count">${c} / ${s.length}</span></div>${s.map(p=>`<div class="mrow"><button class="check${done.has(p.id)?' done':''}" data-id="${p.id}" aria-pressed="${done.has(p.id)}" aria-label="${T('a.tick')}: ${esc(p.t)}">✓</button><span class="tasktitle${done.has(p.id)?' done':''}">${esc(p.t)}</span>${p.p=='High'?`<span class="priority">${T('pri.high')}</span>`:''}<button class="pplay" data-act="pomo" data-id="${p.id}" aria-label="${T('a.timer')}: ${esc(p.t)}">▶</button></div>`).join('')}</div>`}).join('')||`<p class="paneldesc">${T('tp.none')}</p>`}
function startBanner(){return started()?'':`<div class="banner">${T('start.future',{d:dd(1,1).full})}</div>`}

// ---------- Dashboard ----------
function vDash(){const pl=pendingList(),x=dd(cur.w,cur.d);
return hd(`${T('day.n',{n:co()})} / ${planLen()} · ${T('week.n',{n:cur.w})} · ${x.dow} ${x.day} ${x.mon}`,T('dash.h1'),T('dash.sub'),`<div class="row2"><button class="secondary" data-act="overall">◎ ${T('ov.title')}</button><button class="secondary" data-act="build">✎ ${T('dash.build')}</button><button class="primary" data-tab="today">${T('dash.continue')} <span aria-hidden="true">↗</span></button></div>`)+startBanner()+(P.some(p=>!p.arch)?'':`<div class="banner">${T('dash.empty')} <button class="link" data-act="build">${T('nav.plan')} ↗</button></div>`)+stats()+
`<div class="layout"><div>${todayProg()}${hoursDash()}${focusPanel(1)}${panel(T('dash.routine'),T('dash.routineDesc'),`<button class="link" data-tab="today">${T('open')} ↗</button>`,dayList())}${panel(T('dash.week'),T('dash.weekDesc',{a:ord(cur.w,1),b:ord(cur.w,7)}),`<button class="link" data-tab="week">${T('dash.viewWeek')}</button>`,strip(0))}</div>
<aside>${panel(T('ws.title',{w:cur.w}),T('ws.desc',{a:ord(cur.w,1),b:ord(cur.w,7)}),`<button class="link" data-tab="week">${T('nav.week')} ↗</button>`,weekSummary(cur.w))}${panel(T('dash.refl'),T('dash.reflDesc'),`<button class="link" data-tab="notes">${T('viewAll')}</button>`,sorted().slice(0,2).map(r=>reflCard(r,0)).join('')||`<p class="paneldesc">${T('notes.none')}</p>`)}
${panel(T('dash.pending'),T('dash.pendingDesc'),`<span class="pending-count">${T('n.items',{n:pl.length})}</span>`,(pl.slice(0,4).map(p=>`<div class="pending-item"><div class="pending-bullet">!</div><div class="pending-copy"><strong>${esc(p.t)}</strong><small>${labf(p.w,p.d)}</small></div>${p.p=='High'?`<span class="pending-count">${T('pri.high')}</span>`:''}</div>`).join('')||`<p class="paneldesc">${T('pend.nothing')}</p>`)+pendSug()+`<div style="margin-top:14px"><button class="secondary" style="width:100%" data-tab="pending">${T('dash.review')}</button></div>`)}
${panel(T('dash.tipTitle'),T('dash.tipDesc'),'<span class="dot"></span>',`<p style="font-family:'Tiro Bangla',serif;font-size:15px;line-height:1.85;color:var(--ink-soft);margin:0">${T('tip.'+(co()%3))}</p>`)}</aside></div><div class="footer-note">Routine · ${esc(ME?ME.name:'')}</div>`}

// ---------- Today ----------
function topicForm(o,pre){const w=od(o)[0];if(!SUBJ.length)return `<p class="paneldesc">${T('tf.noSubj')} <button class="link" data-tab="settings">${T('nav.settings')} ↗</button></p>`;
return `<div class="tform"><select id="${pre}s" aria-label="${T('subject')}">${SUBJ.map(([k])=>`<option value="${k}"${TF.s==k?' selected':''}>${esc(sn(k,w))}</option>`).join('')}</select><input type="text" id="${pre}t" placeholder="${T('tf.ph')}" aria-label="${T('topic')}"><input type="number" id="${pre}m" min="0" class="tmin" placeholder="${T('pl.minPh')}" aria-label="${T('ce.min')}"><select id="${pre}p" aria-label="${T('priority')}">${priOpts(TF.p)}</select><button class="primary" data-act="tfadd" data-o="${o}" data-pre="${pre}">+ ${T('add')}</button></div>`}
function subjPanel(k,w,d,s,today){const o=ord(w,d),all=s.length&&cnt(s)==s.length,q=qadd==k+'|'+o;
return panel(esc(sn(k,w)),T('sp.desc',{n:s.length,d:cnt(s)})+(all?' · '+T('sp.all'):''),`<span class="row2"><button class="link" data-act="qadd" data-k="${k}" data-o="${o}">+ ${T('topic')}</button>${today?`<button class="link" data-act="subtick" data-sub="${k}">${all?T('sp.untickAll'):T('sp.tickAll')}</button>`:''}</span>`,
`<div class="task-list">${s.map(taskRow).join('')}</div>${q?`<div class="row2" style="margin-top:12px"><input type="text" id="qat" placeholder="${T('sp.ph',{s:esc(sn(k,w))})}" style="flex:1;min-width:160px" aria-label="${T('topic')}"><button class="mini p" data-act="qsave" data-k="${k}" data-o="${o}">${T('add')}</button><button class="mini" data-act="qcancel">${T('cancel')}</button></div>`:''}`)}
function vToday(){const ps=act(cur.w,cur.d),x=dd(cur.w,cur.d),ok=ps.length&&cnt(ps)==ps.length,cl=closed[co()];
let h=hd(`${labf(cur.w,cur.d)} · ${x.dow} ${x.day} ${x.mon}`,T('today.h1'),T('today.sub'),`<button class="${cl?'secondary':'primary'}" data-act="dayclose">${cl?'✓ '+T('today.closed'):T('today.close')}</button>`)+startBanner();
if(RM.length)h+=`<div class="banner">⏰ ${T('rem.missed')}: ${RM.map(m=>`${esc(m.m)} (${m.t})`).join(', ')} <button class="mini" data-act="remclear">${T('rem.dismiss')}</button></div>`;
if(pendCount())h+=`<div class="banner">${T('today.pending',{n:pendCount()})} <button class="link" data-tab="pending">${T('see')} ↗</button></div>`;
h+=panel(T('today.prog'),T('tp.done',{d:cnt(ps),n:ps.length})+(ok?' · '+T('tp.complete'):'')+' · '+T('pl.vs',{p:fmtM(planMin(co())),l:hm(SEC[co()])}),`<span class="link">${T('pct.complete',{n:pc(ps)})}</span>`,`<div class="progress"><span style="width:${pc(ps)}%"></span></div>${planNote(co())}`);
h+=hoursPanel(cur.w,cur.d)+focusPanel(0)+revPanel(co());
h+=panel('+ '+T('today.newTopic'),T('today.newTopicDesc'),'',topicForm(co(),'tf'));
SUBJ.forEach(([k])=>{const s=ps.filter(p=>p.s==k);if(s.length)h+=subjPanel(k,cur.w,cur.d,s,1)});return h}

// ---------- week summary ----------
function weekSummary(w,compact){const el=[...Array(7)].map((_,i)=>ord(w,i+1)).filter(o=>o<=co()),pp=P.filter(p=>!p.arch&&p.w==w&&ord(p.w,p.d)<=co());
const pm=el.reduce((a,o)=>a+planMin(o),0),ts=el.reduce((a,o)=>a+(SEC[o]||0),0),h=el.reduce((a,o)=>a+hrs(o),0),ht=el.reduce((a,o)=>a+tgt(o),0),hit=el.filter(o=>hrs(o)>=tgt(o)).length,pend=pp.filter(p=>ord(p.w,p.d)<co()&&!done.has(p.id)).length;
const subs=SUBJ.map(([k])=>{const s=pp.filter(p=>p.s==k);return s.length?[k,pc(s),cnt(s),s.length,P.filter(p=>p.w==w&&p.s==k).reduce((a,p)=>a+(p.sec||0),0)]:null}).filter(Boolean).sort((a,b)=>a[1]-b[1]);
// "behind" only counts earlier days - today's topics aren't late yet
const behind=SUBJ.map(([k])=>{const s=pp.filter(p=>p.s==k&&ord(p.w,p.d)<co());return s.length&&pc(s)<100?[k,pc(s)]:null}).filter(Boolean).sort((a,b)=>a[1]-b[1]).slice(0,2);
return `<div class="row2"><span class="chip">${T('tp.hours')} <b>${h} / ${ht}</b></span>${pm?`<span class="chip">📋 ${T('pl.vs',{p:fmtM(pm),l:hm(ts)})}</span>`:''}<span class="chip">${T('ws.hit')} <b>${T('ws.days',{d:hit,n:el.length})}</b></span>${ts>=60?`<span class="chip">⏱ ${T('ws.log')} <b>${hm(ts)}</b></span>`:''}${(f=>f?`<span class="chip">🎯 ${T('fg.focus')} <b>${f.p}%</b> · ${T('fg.left',{n:f.n})}${f.br?' · '+T('fg.brokenShort',{n:f.br}):''}</span>`:'')(el.length?focusPct(el[0],el[el.length-1]):null)}<span class="chip">${T('ws.tasks')} <b>${cnt(pp)} / ${pp.length}</b></span><span class="chip${pend?' err':''}">${T('nav.pending')} <b>${pend}</b></span></div>`+
(compact?'':`<div class="subject-list" style="margin-top:16px">${subs.map(([k,x,c,n,t])=>`<div class="subject-row"><div class="subject-name">${esc(sn(k,w))}${t>=60?`<small class="paneldesc" style="display:block">⏱ ${hm(t)}</small>`:''}</div><div class="progress"><span style="width:${x}%"></span></div><div class="subject-count">${c} / ${n}</div></div>`).join('')}</div>`)+
`<p class="paneldesc" style="margin-top:14px">${!el.length?T('ws.notStarted'):behind.length?T('ws.behind',{s:behind.map(([k,x])=>`<b>${esc(sn(k,w))} (${x}%)</b>`).join(', ')}):T('ws.onTrack')}</p>`}

// ---------- Week ----------
function vWeek(){const w=wkW,ps=act(w,wkSel),x=dd(w,wkSel),n=weeks().length;
const nav=`<div class="row2"><button class="secondary" data-act="wkw" data-w="${w-1}"${w<=1?' disabled':''} aria-label="${T('week.prev')}">‹</button><button class="secondary" data-act="wkw" data-w="${w+1}"${w>=n?' disabled':''} aria-label="${T('week.next')}">›</button><button class="${wEdit?'primary':'secondary'}" data-act="wedit">${wEdit?'✓ '+T('week.editDone'):'✎ '+T('week.edit')}</button><button class="secondary" data-act="printopen">🖨 ${T('print')}</button></div>`;
let h=hd(`${T('week.n',{n:w})} / ${n} · ${T('days.range',{a:ord(w,1),b:ord(w,7)})}`,T('week.h1'),wEdit?T('week.subEdit'):T('week.sub'),nav);
if(wEdit)return h+panel(T('week.editTitle',{w}),T('week.editDesc'),'',weekEditor(w));
h+=panel(T('week.7'),T('week.7desc'),'',strip(wkSel,w))+panel(T('ws.title',{w}),T('ws.soFar'),'',weekSummary(w))+panel(`${labf(w,wkSel)} · ${x.day} ${x.mon}`,T('week.dayDone',{d:cnt(ps),n:ps.length}),`<span class="link">${T('pct.complete',{n:pc(ps)})}</span>`,subjBars(ps,w))+hoursPanel(w,wkSel)+revPanel(ord(w,wkSel));
SUBJ.forEach(([k])=>{const s=ps.filter(p=>p.s==k);if(s.length)h+=subjPanel(k,w,wkSel,s,0)});
if(!ps.length)h+=panel(T('week.emptyDay'),T('week.emptyDayDesc'),'','');return h}

// ---------- Pending ----------
function pendSug(){const pl=pendingList();if(!pl.length)return'';const L=[...ALL.filter(([w,d])=>ord(w,d)>=co())].sort((a,b)=>act(...a).length-act(...b).length)[0];if(!L)return'';
return `<div class="sugbox"><span>💡 ${T('pend.sug',{d:`<b>${labf(...L)}</b>`,n:act(...L).length,p:pl.length})}</span><button class="mini p" data-act="mergeall" data-to="${L[0]}.${L[1]}">${T('pend.sendAll')}</button></div>`}
function sugg(){const Tt=ALL.filter(([w,d])=>ord(w,d)>co()),o=[],d7=Tt.find(x=>x[1]==7),nx=Tt[0],lt=[...Tt].sort((a,b)=>act(...a).length-act(...b).length)[0];
[[d7,T('pend.revDay')],[nx,T('pend.next')],[lt,T('pend.light')]].forEach(([x,l])=>{if(x&&!o.some(q=>q[0]==x))o.push([x,l])});return o}
function vPending(){const g={};pendingList().forEach(p=>(g[p.ow+'.'+p.od]=g[p.ow+'.'+p.od]||[]).push(p));
const K=Object.keys(g).sort((a,b)=>ord(...a.split('.').map(Number))-ord(...b.split('.').map(Number)));
const opts=ALL.filter(([w,d])=>ord(w,d)>=co()).map(([w,d])=>`<option value="${w}.${d}">${labf(w,d)} (${act(w,d).length})</option>`).join('');
let h=hd(T('pend.eyebrow'),T('nav.pending'),T('pend.sub'))+(pendSug()?pendSug().replace('sugbox"','sugbox" style="margin:0 0 20px"'):'');h+=overdueHtml();
if(!K.length&&!overdueRevs().length)h+=panel(T('pend.okTitle'),T('pend.okDesc'),'',`<p class="paneldesc">${T('pend.okBody')}</p>`);
K.forEach(k=>{const[w,d]=k.split('.').map(Number);
h+=panel(labf(w,d),`${dd(w,d).day} ${dd(w,d).mon} · ${T('pend.left',{n:g[k].length})}`,`<span class="pending-count">${T('n.items',{n:g[k].length})}</span>`,
g[k].map(p=>`<div class="pending-item"><div class="pending-bullet">!</div><div class="pending-copy"><strong>${esc(p.t)}</strong><small>${esc(sn(p.s,p.w))}</small></div>${p.p=='High'?`<span class="pending-count">${T('pri.high')}</span>`:''}</div>`).join('')+
`<p class="paneldesc" style="margin:18px 0 8px">${T('pend.mergeQ')}</p><div class="row2">${sugg().map(([x,l])=>`<button class="chip" data-act="merge" data-g="${k}" data-to="${x[0]}.${x[1]}">→ ${lab(...x)} <b>(${act(...x).length})</b> · ${l}</button>`).join('')}</div><div class="row2" style="margin-top:12px"><select id="ms-${k}" aria-label="${T('pend.target')}">${opts}</select><button class="secondary" data-act="mergesel" data-g="${k}">${T('pend.mergeSel')}</button></div>`)});return h}

// ---------- Notes ----------
function vNotes(){const cd=rfDay,ex=refl.find(r=>r.w==cd.w&&r.d==cd.d),x=dd(cd.w,cd.d),tn=Object.keys(notes).map(Number).map(i=>P.find(p=>p.id==i)).filter(Boolean);
return hd(T('notes.eyebrow'),T('nav.notes'),T('notes.sub'))+`<div class="layout"><div>${panel(`${T('notes.refl')} - ${lab(cd.w,cd.d)} · ${x.day} ${x.mon}`,T('notes.reflDesc'),'',`<textarea id="rf" aria-label="${T('notes.refl')}">${esc(ex?ex.t:'')}</textarea><div class="row2" style="margin-top:10px"><button class="primary" data-act="rfsave">${T('notes.save')}</button>${cd.w!=cur.w||cd.d!=cur.d?`<button class="secondary" data-act="rfedit" data-w="${cur.w}" data-d="${cur.d}">${T('notes.backToday')}</button>`:''}</div>`)}${panel(T('notes.all'),T('notes.count',{n:refl.length}),'',sorted().map(r=>reflCard(r,1)).join('')||`<p class="paneldesc">${T('notes.none')}</p>`)}</div>
<aside>${panel(T('notes.task'),T('notes.taskDesc'),`<span class="pending-count">${tn.length}</span>`,tn.map(p=>`<div class="pending-item"><div class="quoteicon">▤</div><div class="pending-copy"><strong>${esc(p.t)}</strong><small>${lab(p.w,p.d)}</small><div class="tasknote">${esc(notes[p.id])}</div></div></div>`).join('')||`<p class="paneldesc">${T('notes.taskNone')}</p>`)}</aside></div>`}

// ---------- Routine: weeks, CSV, revision, archive ----------
function weekEditor(w){let t='';const subSel=(id,sel)=>`<select id="${id}" aria-label="${T('subject')}" style="flex:0 1 210px;min-width:130px">${SUBJ.map(([k])=>`<option value="${k}"${sel==k?' selected':''}>${esc(sn(k,w))}</option>`).join('')}</select>`,addRow=k=>`<div class="sp">${subSel('adds',k)}<input type="text" id="addt" placeholder="${T('tf.ph')}"><input type="number" id="addm" min="0" placeholder="${T('pl.minPh')}" style="width:80px" aria-label="${T('ce.min')}"><button class="mini p" data-act="addsave">${T('add')}</button><button class="mini" data-act="cancel">${T('cancel')}</button></div>`;
ALL.filter(x=>x[0]==w).forEach(([,d])=>{const ps=act(w,d),x=dd(w,d),isAdd=adding&&adding.w==w&&adding.d==d;
t+=`<div class="dr"><div class="row2"><b style="color:var(--navy-deep)">${lab(w,d)}</b><span class="paneldesc">${wd(w,d)} · ${x.dow} ${x.day} ${x.mon} · ${T('we.done',{d:cnt(ps),n:ps.length})}</span><button class="mini p" style="margin-left:auto" data-act="addopen" data-w="${w}" data-d="${d}" data-k="">+ ${T('topic')}</button></div>`;
if(!ps.length&&!isAdd)t+=`<p class="paneldesc" style="margin:6px 0 0 10px">${T('we.none')}</p>`;
SUBJ.forEach(([k])=>{const s=ps.filter(p=>p.s==k);if(!s.length)return;
t+=`<div class="sh">${renaming==k+w?`<input type="text" id="rnm" value="${esc(sn(k,w))}" aria-label="${T('subject')}"><button class="mini p" data-act="rnsave" data-k="${k}" data-w="${w}">${T('save')}</button><button class="mini" data-act="cancel">${T('cancel')}</button>`:`<b>${esc(sn(k,w))}</b><span class="paneldesc">${cnt(s)}/${s.length}</span><button class="mini" data-act="addopen" data-w="${w}" data-d="${d}" data-k="${k}" style="margin-left:auto">+ ${T('topic')}</button>`}</div>`;
s.forEach(p=>{t+=editing==p.id?`<div class="sp"><input type="text" id="edt" value="${esc(p.t)}" aria-label="${T('topic')}">${subSel('eds',p.s)}<input type="number" id="edm" min="0" value="${p.est||''}" placeholder="${SMIN[p.s]||T('pl.minPh')}" style="width:80px" aria-label="${T('ce.min')}"><select id="edp" aria-label="${T('priority')}">${priOpts(p.p)}</select><select id="edd" aria-label="${T('b.day')}">${dayOpts(w+'.'+d)}</select><button class="mini p" data-act="save" data-id="${p.id}">${T('save')}</button><button class="mini" data-act="cancel">${T('cancel')}</button></div>`:`<div class="sp${done.has(p.id)?' dn':''}"><span class="txt">${done.has(p.id)?'✓ ':''}${esc(p.t)} ${pr(p.p)}${estOf(p)?` <span class="tag">⏱ ${fmtM(estOf(p))}</span>`:''}${p.from?` <span class="fromtag">${T('from',{d:p.from})}</span>`:''}</span><button class="mini" data-act="edit" data-id="${p.id}">${T('edit')}</button><button class="mini danger" data-act="arch" data-id="${p.id}">${T('archive')}</button></div>`});
if(isAdd&&adding.k==k)t+=addRow(k)});
if(isAdd&&!adding.k)t+=addRow('');
t+='</div>'});return t}
// a section that folds open/closed and remembers it while the app is open
const fold=(key,title,desc,body,def)=>`<details class="fold panel" data-fold="${key}"${(FOLD[key]??def)?' open':''}><summary><div><h2>${title}</h2><p class="paneldesc">${desc}</p></div><span class="fchev" aria-hidden="true">▾</span></summary><div class="fbody">${body}</div></details>`;
// every week as a small card: which subjects it covers and how far along it is
function weekCards(){const n=weeks().length,spread={};P.forEach(p=>{if(!p.arch)(spread[p.s]=spread[p.s]||new Set()).add(p.w)});
// subjects special to a week come first (e.g. General Science), everyday ones (English, Maths) after
return `<div class="wcards">${weeks().map(w=>{const ps=P.filter(p=>!p.arch&&p.w==w),x=pc(ps),a=dd(w,1),b=dd(w,7),now=w==cur.w,c={};
ps.forEach(p=>c[p.s]=(c[p.s]||0)+1);const ss=Object.keys(c).sort((k1,k2)=>spread[k1].size-spread[k2].size||c[k2]-c[k1]),chips=ss.slice(0,3).map(k=>`<span class="tag">${esc(sn(k))}</span>`).join('')+(ss.length>3?`<span class="tag">+${ss.length-3}</span>`:'');
return `<div class="wcard${now?' now':''}"><div class="wtop"><span class="wk">${T('week.n',{n:w})}${now?' · '+T('w.today'):''}</span><button class="wx" data-act="wdel" data-w="${w}"${n<2?' disabled':''} aria-label="${T('wk.remove',{w})}" title="${T('wk.remove',{w})}">✕</button></div>
<button class="wbody" data-act="wtable" data-w="${w}" aria-label="${T('wk.editTable',{w})}"><small>${T('days.range',{a:ord(w,1),b:ord(w,7)})} · ${a.day} ${a.mon} – ${b.day} ${b.mon}</small><span class="wchips">${chips||`<span class="paneldesc">${T('we.none')}</span>`}</span><span class="progress"><span style="width:${x}%"></span></span><small>${T('wc.done',{d:cnt(ps),n:ps.length,x})}${(m=>m?' · 📋 '+hShort(m):'')(ps.reduce((t,p)=>t+estOf(p),0))}</small></button>
<div class="wfoot"><button class="link" data-act="wtable" data-w="${w}">✎ ${T('wk.edit')}</button><button class="link" data-act="wopen" data-w="${w}">${T('wk.open')} ↗</button></div></div>`}).join('')}<button class="wcard add" data-act="addweek">+ ${T('plan.addWeek')}</button></div>`}
function vPlan(){const ar=P.filter(p=>p.arch),ac=revs.filter(r=>!r.done);
return hd(T('plan.eyebrow'),T('nav.plan'),T('plan.sub'),`<div class="row2"><button class="primary" data-act="addtopics">+ ${T('plan.addTopics')}</button><button class="secondary" data-act="upload">⬆ ${T('plan.upload')}</button></div>`)+
`<div class="row2 ptools"><button class="mini" data-act="export">⬇ ${T('plan.export')}</button><button class="mini" data-act="template">⬇ ${T('plan.tpl')}</button><button class="mini" data-act="printopen">🖨 ${T('print')}</button></div>`+
panel(T('plan.weeks'),T('plan.weeksDesc'),'',weekCards())+
fold('rev',T('plan.rev')+(ac.length?` <span class="pending-count">${ac.length}</span>`:''),T('plan.revDesc'),`<p class="paneldesc" style="margin-bottom:6px">${T('plan.revInt')}</p><div class="row2"><input type="text" id="lad" value="${LAD.join(',')}" style="width:180px" aria-label="${T('plan.revInt')}"><button class="secondary" data-act="ladsave">${T('save')}</button></div><div style="margin-top:16px">${ac.sort((a,b)=>a.o-b.o).map(r=>{const p=P.find(q=>q.id==r.pid);return p?`<div class="sp"><span class="txt"><span class="revtag">${dlab(r.o)}</span> ${esc(p.t)} · ${T('rev.nth',{n:r.step})}</span><button class="mini danger" data-act="revdel" data-r="${r.id}">${T('remove')}</button></div>`:''}).join('')||`<p class="paneldesc">${T('plan.revNone')}</p>`}</div>`)+
fold('arch',T('plan.arch')+(ar.length?` <span class="pending-count">${ar.length}</span>`:''),T('plan.archDesc'),ar.map(p=>`<div class="sp"><span class="txt">${esc(p.t)} <span class="tag">${lab(p.w,p.d)}</span></span><button class="mini" data-act="restore" data-id="${p.id}">${T('restore')}</button></div>`).join('')||`<p class="paneldesc">${T('nothing')}</p>`)}

// ---------- Settings ----------
const gp=k=>k.split('.').reduce((o,x)=>o[x],SET),sp=(k,v)=>{const a=k.split('.'),l=a.pop();a.reduce((o,x)=>o[x],SET)[l]=v};
const stog=(k,l,d)=>`<div class="srow"><span>${l}${d?`<small>${d}</small>`:''}</span><button class="sw${gp(k)?' on':''}" data-act="stog" data-k="${k}" aria-pressed="${!!gp(k)}" aria-label="${l}"></button></div>`;
const snum=(k,l,mn,mx,d)=>`<div class="srow"><span>${l}${d?`<small>${d}</small>`:''}</span><input type="number" data-set="${k}" min="${mn}" max="${mx}" value="${gp(k)}" style="width:84px" aria-label="${l}"></div>`;
function subjSettings(){return SUBJ.map(([k],i)=>{const n=P.filter(p=>p.s==k).length;return `<div class="sp">${renaming==k+'0'?`<input type="text" id="rnm" value="${esc(SNAME[k])}" aria-label="${T('subject')}"><button class="mini p" data-act="rnsave" data-k="${k}" data-w="0">${T('save')}</button><button class="mini" data-act="cancel">${T('cancel')}</button>`:
`<span class="txt">${esc(SNAME[k])} <span class="tag">${T('n.tasks',{n})}</span></span><label class="paneldesc smin" title="${T('pl.perTopicHint')}">⏱ <input type="number" min="0" data-smin="${k}" value="${SMIN[k]||''}" placeholder="0" aria-label="${T('pl.perTopic')}"> ${T('pl.perTopic')}</label><button class="mini" data-act="smove" data-i="${i}" data-dir="-1"${i==0?' disabled':''} aria-label="${T('up')}">↑</button><button class="mini" data-act="smove" data-i="${i}" data-dir="1"${i==SUBJ.length-1?' disabled':''} aria-label="${T('down')}">↓</button><button class="mini" data-act="rn" data-k="${k}" data-w="0">${T('rename')}</button><button class="mini danger" data-act="sdel" data-k="${k}"${n?` disabled title="${T('subj.inUse',{n})}"`:''}>${T('delete')}</button>`}</div>`}).join('')+
`<div class="row2" style="margin-top:10px"><input type="text" id="snew" placeholder="${T('subj.newPh')}" style="flex:1;min-width:160px" aria-label="${T('subj.newPh')}"><button class="secondary" data-act="sadd">+ ${T('subject')}</button></div>`}
function vSettings(){const seg=(act,cur,list)=>`<div class="seg" style="margin-top:0">${list.map(([k,l])=>`<button data-act="${act}" data-v="${k}"${cur==k?' class="on"':''} aria-pressed="${cur==k}">${l}</button>`).join('')}</div>`;
return hd(T('set.eyebrow'),T('nav.settings'),T('set.sub'))+`<div class="layout"><div>`+
panel(T('set.lang'),T('set.langDesc'),'',seg('lang',LANG(),[['en','English'],['bn','বাংলা']]))+
panel(T('set.theme'),T('set.themeDesc'),'',seg('theme',SET.theme,[['light','☀ '+T('set.light')],['dark','☾ '+T('set.dark')],['system','⚙ '+T('set.system')]])+`<p class="paneldesc" style="margin-top:10px">${T('set.themeHint')}</p>`)+
panel(T('set.subjects')+` · <small style="font-weight:500;color:var(--muted)">${esc(PROJ?PROJ.name:'')}</small>`,T('set.subjectsDesc'),'',subjSettings())+
panel(T('set.study'),T('set.studyDesc'),'',`<p class="paneldesc" style="margin:0 0 6px">${T('set.start')}</p><div class="row2"><input type="date" id="startDate" value="${START}"><span class="paneldesc">${T('set.startHint',{d:co()})}</span></div><p class="paneldesc" style="margin:16px 0 6px">${T('set.target')}</p><div class="row2">${tgSel()}<span class="paneldesc">${T('set.targetHint')}</span></div>`)+
`</div><aside>`+
panel('🎯 '+T('fg.title'),T('fg.desc'),'',stog('fg.on',T('fg.on'),T('fg.onHint'))+(SET.fg.on?snum('fg.grace',T('fg.grace'),0,120,T('fg.graceHint'))+`<div class="srow"><span>${T('fg.mode')}<small>${T('fg.modeHint')}</small></span><select data-setv="fg.mode" aria-label="${T('fg.mode')}"><option value="pause"${SET.fg.mode=='pause'?' selected':''}>${T('fg.mPause')}</option><option value="nocount"${SET.fg.mode=='nocount'?' selected':''}>${T('fg.mNocount')}</option></select></div>`+`<div class="srow"><span>${T('fg.alert')}<small>${T('fg.alertHint')}</small></span><span class="row2" style="flex-wrap:nowrap"><select data-setv="fg.alert" aria-label="${T('fg.alert')}">${[['alarm',T('fg.aAlarm')],['gentle',T('fg.aGentle')],['off',T('fg.aOff')]].map(([v,l])=>`<option value="${v}"${fgAlert()==v?' selected':''}>${l}</option>`).join('')}</select><button class="mini" data-act="atest">${T('fg.testAlarm')}</button></span></div>`+stog('fg.blur',T('fg.blur'),T('fg.blurHint'))+stog('fg.strict',T('fg.strict'),T('fg.strictHint'))+(SET.fg.strict?snum('fg.strictMin',T('fg.strictMin'),1,30):''):'')+`<p class="paneldesc" style="margin-top:10px">${T('fg.note')}</p>`)+
panel(T('set.pomo'),T('set.pomoDesc'),'',snum('pomo.focus',T('set.focusMin'),1,180)+snum('pomo.short',T('set.shortMin'),1,60)+snum('pomo.long',T('set.longMin'),1,90)+snum('pomo.every',T('set.every'),2,10)+
stog('pomo.auto',T('set.auto'),T('set.autoHint'))+stog('pomo.autoHour',T('set.autoHour'),T('set.autoHourHint')))+
panel(T('set.sound'),T('set.soundDesc'),'',stog('snd.on',T('set.sndTimer'),T('set.sndTimerHint'))+stog('snd.hour',T('set.sndHour'),T('set.sndHourHint'))+
`<div class="srow"><span>${T('set.notif')}<small>${T('set.notifHint')}</small></span><button class="sw${SET.notif?' on':''}" data-act="notif" aria-pressed="${!!SET.notif}" aria-label="${T('set.notif')}"></button></div><div class="srow"><span>${T('set.vol')}</span><input type="range" data-set="snd.vol" min="0" max="1" step="0.05" value="${SET.snd.vol}" aria-label="${T('set.vol')}"></div><div class="row2" style="margin-top:12px"><span class="paneldesc">${T('set.listen')}</span><button class="mini" data-act="stest" data-v="focus">${T('set.tFocus')}</button><button class="mini" data-act="stest" data-v="brk">${T('set.tBreak')}</button><button class="mini" data-act="stest" data-v="hour">${T('set.tHour')}</button><button class="mini" data-act="stest" data-v="target">${T('set.tTarget')}</button></div>`)+
panel(T('rem.title'),T('rem.desc'),'',(RM.length?`<div class="banner">⏰ ${T('rem.missed')}: ${RM.map(m=>`${esc(m.m)} (${m.t})`).join(', ')} <button class="mini" data-act="remclear">${T('rem.dismiss')}</button></div>`:'')+(R.map((r,i)=>`<div class="rem"><div><b>${r.r=='weekly'?T('rem.weeklyOn',{d:DOWS()[r.dow]}):T('rem.daily')} · ${r.t}</b><div class="paneldesc">${esc(r.m)}</div></div><button class="sw${r.on?' on':''}" data-act="remtog" data-i="${i}" aria-pressed="${r.on}" aria-label="${T('rem.toggle')}"></button><button class="mini danger" data-act="remdel" data-i="${i}" aria-label="${T('delete')}">✕</button></div>`).join('')||`<p class="paneldesc">${T('rem.none')}</p>`)+`<div class="row2" style="margin-top:14px"><input type="time" id="rT" value="07:00" aria-label="${T('rem.time')}"><select id="rR" aria-label="${T('rem.repeat')}"><option value="daily">${T('rem.daily')}</option><option value="weekly">${T('rem.weekly')}</option></select><input type="text" id="rM" placeholder="${T('rem.ph')}" style="flex:1;min-width:150px"><button class="primary" data-act="remadd">${T('add')}</button></div>`)+
panel(T('set.data'),T('set.dataDesc'),'',`<div class="row2"><button class="secondary" data-act="backup">⬇ ${T('set.backup')}</button><button class="secondary" data-act="tplreset">${T('set.reset')}</button><button class="secondary danger" data-act="wipe">${T('set.wipe')}</button></div>`)+
panel(T('set.account'),VIEW?T('ro.viewing',{n:esc(VIEW.name)}):`${esc(ME.name)} · ${esc(ME.phone)}${ME.is_admin?' · '+T('adm.admin'):''}`,'',`<div class="row2"><button class="secondary danger" data-act="logout">${T('set.logout')}</button></div><p class="paneldesc" style="margin-top:10px">${T('set.noAuth')}</p>`)+`</aside></div>`}

// ---------- Admin ----------
function vAdmin(){const head=hd(T('adm.eyebrow'),T('nav.admin'),T('adm.sub'),`<button class="secondary" data-act="admreload">↻ ${T('adm.refresh')}</button>`);
if(!ADM||ADM.loading)return head+`<div class="empty">${T('loading')}</div>`;if(ADM.err)return head+`<div class="banner">${esc(ADM.err)}</div>`;
const U=ADM.users,PR_=U.flatMap(u=>u.projects.map(p=>p.summary||{})),seen=u=>u.last_seen?new Date(u.last_seen):null,act7=U.filter(u=>seen(u)&&Date.now()-seen(u)<7*864e5).length,avg=k=>PR_.length?Math.round(PR_.reduce((a,s)=>a+(s[k]||0),0)/PR_.length):0;
const fmt=u=>{const d=seen(u);return d?d.toLocaleString(LANG()=='bn'?'bn-BD':'en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'-'};
const bar=n=>`<span class="mbar"><span style="width:${n||0}%"></span></span>${n||0}%`;
const card=(l,v,f)=>`<div class="stat"><div class="statlabel">${l}</div><div class="statvalue">${v}</div><div class="statfoot">${f}</div></div>`;
const rows=U.map(u=>{const me=u.id==ME.id,ps=u.projects.length?u.projects:[{id:0,name:'-',summary:{}}];
return ps.map((pj,i)=>{const s=pj.summary||{};return `<tr${i?' class="sub"':''}>${i?'<td></td>':`<td class="who" rowspan="1"><b>${esc(u.name)} ${u.is_admin?`<span class="role ad">${T('adm.admin')}</span>`:''}</b><small>${esc(u.phone)} · ${fmt(u)}</small></td>`}
<td class="pj">${esc(pj.name)}${u.active_project==pj.id&&ps.length>1?` <span class="role">${T('adm.activeP')}</span>`:''}</td><td class="n">${s.day?`${s.day} / ${s.plan_len}`:'-'}</td><td class="n">${bar(s.overall)}</td><td class="n">${bar(s.on_track)}</td><td class="n">${s.today_done??0} / ${s.today_total??0}${s.plan_min_today?`<small class="paneldesc" style="display:block">📋 ${fmtM(s.plan_min_today)}</small>`:''}</td><td class="n">${s.hours_7d??0}</td><td class="n">${s.streak??0}</td><td class="n">${s.focus_7d==null?'-':`${s.focus_7d}%<small class="paneldesc" style="display:block">${T('fg.left',{n:s.leaves_7d||0})}${s.broken_7d?' · '+T('fg.brokenShort',{n:s.broken_7d}):''}</small>`}</td><td class="n">${s.pending??0}</td>
<td><span class="row2" style="flex-wrap:nowrap">${pj.id?`<button class="mini p" data-act="aview" data-p="${pj.id}">${T('adm.view')}</button>`:''}${i||me?'':`<button class="mini" data-act="arole" data-u="${u.id}" data-v="${u.is_admin?0:1}">${u.is_admin?T('adm.unadmin'):T('adm.mkadmin')}</button><button class="mini danger" data-act="adel" data-u="${u.id}" aria-label="${T('delete')}">✕</button>`}</span></td></tr>`}).join('')}).join('');
return head+`<section class="acards">${card(T('adm.users'),U.length,T('adm.usersFoot',{n:PR_.length}))}${card(T('adm.active'),act7,T('adm.activeFoot'))}${card(T('adm.avgProg'),avg('overall')+'<small>%</small>',T('adm.avgProgFoot'))}${card(T('adm.avgTrack'),avg('on_track')+'<small>%</small>',T('adm.avgTrackFoot'))}</section>`+
panel(T('adm.list'),T('adm.listDesc'),'',U.length?`<div class="twrap"><table class="atable"><thead><tr><th>${T('adm.user')}</th><th>${T('proj.one')}</th><th>${T('adm.day')}</th><th>${T('adm.overall')}</th><th>${T('adm.onTrack')}</th><th>${T('adm.today')}</th><th>${T('adm.h7')}</th><th>${T('hr.streak')}</th><th>🎯 ${T('adm.focus')}</th><th>${T('nav.pending')}</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:`<p class="paneldesc">${T('adm.none')}</p>`)+
panel(T('adm.add'),T('adm.addDesc'),'',`<div class="row2"><input type="text" id="anm" placeholder="${T('login.name')}" style="flex:1;min-width:150px"><input type="tel" id="aph" placeholder="${T('login.phone')}" style="flex:1;min-width:150px"><button class="primary" data-act="aadd">+ ${T('adm.addBtn')}</button></div>`)}

// ---------- Overall: every project of this account at a glance ----------
function vOverall(){const head=hd(T('ov.eyebrow'),T('ov.title'),T('ov.sub'),`<button class="primary" data-act="projnew">+ ${T('proj.new')}</button>`);
if(!OV||OV.loading)return head+`<div class="empty">${T('loading')}</div>`;if(OV.err)return head+`<div class="banner">${esc(OV.err)}</div>`;
const S=PROJS.map(p=>p.summary||{}),sum=k=>S.reduce((a,s)=>a+(s[k]||0),0),card=(l,v,f)=>`<div class="stat"><div class="statlabel">${l}</div><div class="statvalue">${v}</div><div class="statfoot">${f}</div></div>`;
return head+`<section class="acards">${card(T('ov.projects'),PROJS.length,T('ov.projectsFoot'))}${card(T('ov.hoursToday'),sum('hours_today'),T('ov.hoursTodayFoot'))}${card(T('ov.hours7'),sum('hours_7d'),T('ov.hours7Foot'))}${card(T('ov.logged'),hm(sum('logged_min_today')*60),T('ov.loggedFoot',{t:hm(sum('logged_min_7d')*60)}))}</section>`+
`<div class="ovgrid">${PROJS.map(p=>{const s=p.summary||{},on=PROJ&&p.id==PROJ.id;return `<section class="panel ovp${on?' on':''}"><div class="panelhead"><div><h2>${esc(p.name)}</h2><p class="paneldesc">${s.started===false?T('ov.notStarted',{d:s.start}):T('ov.day',{d:s.day,n:s.plan_len})}${on?' · '+T('ov.open'):''}</p></div><button class="${on?'secondary':'primary'}" data-act="projopen" data-p="${p.id}">${on?T('ov.go'):T('open')} ↗</button></div>
<div class="tbig"><span class="tval">${s.overall||0}<small>%</small></span><span class="paneldesc">${T('ov.overallOf',{d:s.done||0,n:s.total||0})}</span></div><div class="progress big"><span style="width:${s.overall||0}%"></span></div>
<div class="row2" style="margin-top:14px"><span class="chip">${T('adm.onTrack')} <b>${s.on_track||0}%</b></span><span class="chip">${T('adm.today')} <b>${s.today_done||0} / ${s.today_total||0}</b></span><span class="chip">${T('tp.hours')} <b>${s.hours_today||0} / ${s.target||0}</b></span><span class="chip">📋 ${T('pl.vs',{p:fmtM(s.plan_min_today||0),l:hm((s.logged_min_today||0)*60)})}</span><span class="chip${s.pending?' err':''}">${T('nav.pending')} <b>${s.pending||0}</b></span><span class="chip">${T('hr.streak')} <b>${T('n.days',{n:s.streak||0})}</b></span>${s.focus_7d!=null?`<span class="chip">🎯 ${T('fg.focus')} <b>${s.focus_7d}%</b> · ${T('fg.left',{n:s.leaves_7d||0})}</span>`:''}</div></section>`}).join('')}</div>`}

// ---------- project menu (from the logo) and "new project" ----------
function projMenuHtml(){const ren=projUI.ren;
return `<div class="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="pmt"><div class="eyebrow">${T('proj.eyebrow')}</div><h2 id="pmt" style="font-size:22px;font-family:Fraunces,Georgia,serif;color:var(--navy-deep);margin-bottom:12px">${T('proj.title')}</h2>
<button class="pitem ov" data-act="overall"><span>◎ ${T('ov.title')}</span><small>${T('ov.short')}</small></button>
<div class="plist">${PROJS.map(p=>{const s=p.summary||{},on=PROJ&&p.id==PROJ.id;return ren==p.id?`<div class="pitem edit"><input type="text" id="prn" value="${esc(p.name)}" aria-label="${T('proj.name')}"><button class="mini p" data-act="projrensave" data-p="${p.id}">${T('save')}</button><button class="mini" data-act="projren" data-p="0">${T('cancel')}</button></div>`:
`<div class="pitem${on?' on':''}"><button class="pmain" data-act="projopen" data-p="${p.id}"><span>${on?'● ':''}${esc(p.name)}</span><small>${T('ov.day',{d:s.day||1,n:s.plan_len||1})} · ${s.overall||0}% · ${T('adm.today')} ${s.today_done||0}/${s.today_total||0}</small></button><button class="mini" data-act="projren" data-p="${p.id}">${T('rename')}</button><button class="mini danger" data-act="projdel" data-p="${p.id}"${PROJS.length<2?' disabled':''} aria-label="${T('delete')}">✕</button></div>`}).join('')}</div>
<div class="row2" style="margin-top:16px;justify-content:space-between"><button class="secondary" data-act="projclose">${T('close')}</button><button class="primary" data-act="projnew">+ ${T('proj.new')}</button></div></div></div>`}
function projNewHtml(){const n=projUI,src=[['template',T('proj.srcTpl')],['csv',T('proj.srcCsv')],['empty',T('proj.srcEmpty')]];
return `<div class="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="pnt"><div class="eyebrow">${T('proj.eyebrow')}</div><h2 id="pnt" style="font-size:22px;font-family:Fraunces,Georgia,serif;color:var(--navy-deep);margin-bottom:6px">${T('proj.new')}</h2><p class="paneldesc">${T('proj.newDesc')}</p>
<label class="lfield">${T('proj.name')}<input type="text" id="pnn" value="${esc(n.name||'')}" placeholder="${T('proj.namePh')}"></label>
<label class="lfield">${T('proj.start')}<input type="date" id="pns" value="${n.start||todayISO()}"></label>
<p class="paneldesc" style="margin:16px 0 0;font-weight:700">${T('proj.from')}</p><div class="seg">${src.map(([k,l])=>`<button data-act="projsrc" data-v="${k}"${n.src==k?' class="on"':''}>${l}</button>`).join('')}</div>
<p class="paneldesc" style="margin-top:8px">${T('proj.src_'+n.src)}</p>
${n.src=='csv'?`<div class="row2" style="margin-top:10px"><input type="file" id="pnf" accept=".csv,text/csv" aria-label="${T('proj.srcCsv')}"><span class="paneldesc">${n.file?esc(n.file):''}</span></div>`:''}
${n.err?`<p class="lerr">${esc(n.err)}</p>`:''}
<div class="row2" style="margin-top:18px;justify-content:flex-end"><button class="secondary" data-act="projclose">${T('cancel')}</button><button class="primary" data-act="projcreate">${T('proj.create')}</button></div></div></div>`}

// ---------- Login ----------
function vLogin(){return `<div class="login"><div class="lcard"><div class="brandmark big">R</div><h1>${T('login.title')}</h1><p class="subtitle">${LG.need?T('login.newSub'):T('login.sub')}</p>
<label class="lfield">${T('login.phone')}<input type="tel" id="lphone" inputmode="tel" autocomplete="tel" placeholder="01XXXXXXXXX" value="${esc(LG.phone)}"${LG.need?' readonly':''}></label>
${LG.need?`<label class="lfield">${T('login.name')}<input type="text" id="lname" autocomplete="name" placeholder="${T('login.namePh')}"></label>`:''}
${LG.err?`<p class="lerr">${esc(LG.err)}</p>`:''}
<button class="primary" data-act="login" style="width:100%">${LG.need?T('login.create'):T('login.continue')}</button>
${LG.need?`<p style="text-align:center;margin:12px 0 0"><button class="link" data-act="loginback">← ${T('login.back')}</button></p>`:''}
<p class="paneldesc lnote">${T('login.note')}</p>
<div class="seg" style="justify-content:center">${[['en','English'],['bn','বাংলা']].map(([k,l])=>`<button data-act="lang" data-v="${k}"${LANG()==k?' class="on"':''}>${l}</button>`).join('')}</div></div></div>`}
